const input = require("fs").readFileSync(0, "utf8");

function allPermutations(nums) {
  const sorted = [...nums].sort((a, b) => a - b);
  const permutations = [];
  const path = [];
  const used = new Array(sorted.length).fill(false);

  // Fills the next position with each number not used yet.
  function build() {
    if (path.length === sorted.length) {
      permutations.push([...path]);
      return;
    }
    for (let i = 0; i < sorted.length; i++) {
      if (used[i]) {
        continue;
      }
      used[i] = true;
      path.push(sorted[i]);
      build();
      path.pop();
      used[i] = false;
    }
  }

  build();
  return permutations;
}

const [n, ...nums] = input.trim().split(/\s+/).map(Number);
for (const permutation of allPermutations(nums.slice(0, n))) {
  console.log(permutation.join(" "));
}

