// Fills the next position with each number not used yet.
void build(const std::vector<int>& nums, std::vector<bool>& used, std::vector<int>& path,
           std::vector<std::vector<int>>& permutations) {
    if (path.size() == nums.size()) {
        permutations.push_back(path);
        return;
    }
    for (std::size_t i = 0; i < nums.size(); i++) {
        if (used[i]) {
            continue;
        }
        used[i] = true;
        path.push_back(nums[i]);
        build(nums, used, path, permutations);
        path.pop_back();
        used[i] = false;
    }
}

