import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
    // Fills the next position with each number not used yet.
    static void build(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> permutations) {
        if (path.size() == nums.length) {
            permutations.add(new ArrayList<>(path));
            return;
        }
        for (int i = 0; i < nums.length; i++) {
            if (used[i]) {
                continue;
            }
            used[i] = true;
            path.add(nums[i]);
            build(nums, used, path, permutations);
            path.remove(path.size() - 1);
            used[i] = false;
        }
    }

    static List<List<Integer>> allPermutations(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> permutations = new ArrayList<>();
        build(nums, new boolean[nums.length], new ArrayList<>(), permutations);
        return permutations;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = in.nextInt();
        }
        for (List<Integer> permutation : allPermutations(nums)) {
            StringJoiner line = new StringJoiner(" ");
            for (int num : permutation) {
                line.add(String.valueOf(num));
            }
            System.out.println(line);
        }
    }
}

