package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

func allPermutations(nums []int) [][]int {
	sort.Ints(nums)
	permutations := [][]int{}
	path := []int{}
	used := make([]bool, len(nums))

	// Fills the next position with each number not used yet.
	var build func()
	build = func() {
		if len(path) == len(nums) {
			permutations = append(permutations, append([]int{}, path...))
			return
		}
		for i, num := range nums {
			if used[i] {
				continue
			}
			used[i] = true
			path = append(path, num)
			build()
			path = path[:len(path)-1]
			used[i] = false
		}
	}

	build()
	return permutations
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	for _, permutation := range allPermutations(nums) {
		parts := make([]string, len(permutation))
		for i, num := range permutation {
			parts[i] = strconv.Itoa(num)
		}
		fmt.Println(strings.Join(parts, " "))
	}
}

